import{_ as i,o as l,c as t,a2 as n}from"./chunks/framework.DpXDHk3d.js";const p=JSON.parse('{"title":"4.3 钳形电流表","description":"","frontmatter":{},"headers":[],"relativePath":"electrician/low-voltage-electrician/04-chapter-4-chang-yong-dian-gong-yi-biao/4-3-qian-xing-dian-liu-biao.md","filePath":"electrician/low-voltage-electrician/04-chapter-4-chang-yong-dian-gong-yi-biao/4-3-qian-xing-dian-liu-biao.md","lastUpdated":1793095197000}'),o={name:"electrician/low-voltage-electrician/04-chapter-4-chang-yong-dian-gong-yi-biao/4-3-qian-xing-dian-liu-biao.md"};function s(e,a,r,g,c,h){return l(),t("div",null,[...a[0]||(a[0]=[n(`<h1 id="_4-3-钳形电流表" tabindex="-1">4.3 钳形电流表 <a class="header-anchor" href="#_4-3-钳形电流表" aria-label="Permalink to &quot;4.3 钳形电流表&quot;">​</a></h1><h2 id="本节导读" tabindex="-1">本节导读 <a class="header-anchor" href="#本节导读" aria-label="Permalink to &quot;本节导读&quot;">​</a></h2><p>测电流最麻烦的是要<strong>断开电路串进去</strong>。钳形电流表解决了这个问题——它像一个&quot;钳子&quot;,把导线往钳口里一夹,不用断电就能读出电流。这一节讲它的原理、用法和注意事项。</p><h2 id="一、原理-为什么不用断电就能测" tabindex="-1">一、原理:为什么不用断电就能测 <a class="header-anchor" href="#一、原理-为什么不用断电就能测" aria-label="Permalink to &quot;一、原理:为什么不用断电就能测&quot;">​</a></h2><p>钳形电流表的基本结构,是一个可开合的<strong>电流互感器</strong>:</p><ul><li>铁芯做成&quot;钳口&quot;形状,能把导线<strong>夹进去</strong>;</li><li>被测导线相当于互感器的<strong>一次侧绕组</strong>;</li><li>钳口上的线圈相当于<strong>二次侧绕组</strong>,感应出与被测电流成比例的电流;</li><li>表头读出电流值。</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>       ┌─────────┐</span></span>
<span class="line"><span>       │  铁芯    │</span></span>
<span class="line"><span>  ──────┤钳 口    ├─────► 被测导线从钳口穿过(相当于一次绕组)</span></span>
<span class="line"><span>       └────┬────┘</span></span>
<span class="line"><span>            │ 二次绕组 → 表头</span></span></code></pre></div><blockquote><p>💡 通俗理解:导线成了互感器的&quot;一次侧&quot;,不用拆线、不用断电,夹进去就能&quot;看到&quot;电流。</p></blockquote><h2 id="二、使用方法" tabindex="-1">二、使用方法 <a class="header-anchor" href="#二、使用方法" aria-label="Permalink to &quot;二、使用方法&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>选挡(先大后小) → 开钳口 → 把导线置于钳口中央 → 合钳读数</span></span></code></pre></div><ol><li><strong>选量程</strong>:先估电流,选大档再逐步换小档;</li><li><strong>开钳</strong>:按下扳机张开钳口,把<strong>被测导线</strong>(单根)放入<strong>钳口中央</strong>;</li><li><strong>合钳</strong>:使钳口<strong>闭合紧密</strong>,保持不动,读取读数;</li><li>测量中若读数偏小,可换小档;若读数超量程,立即换大档。</li></ol><blockquote><p>⚠️ <strong>只能夹单根导线</strong>:如果同时夹住两根导线,两根导线的电流会相互抵消,读数错误甚至为零。</p></blockquote><h2 id="三、钳形电流表的类型" tabindex="-1">三、钳形电流表的类型 <a class="header-anchor" href="#三、钳形电流表的类型" aria-label="Permalink to &quot;三、钳形电流表的类型&quot;">​</a></h2><ul><li>多数钳形电流表<strong>只能测量交流电流</strong>(交流钳形表);</li><li>部分型号(交直流两用钳形表)可测直流电流;</li><li>高档型号还能测电压、电阻(相当于&quot;钳形万用表&quot;)。</li></ul><h2 id="四、注意事项" tabindex="-1">四、注意事项 <a class="header-anchor" href="#四、注意事项" aria-label="Permalink to &quot;四、注意事项&quot;">​</a></h2><ul><li>测量前确认量程合适,<strong>从小电流开始</strong>逐档调整;</li><li><strong>钳口要清洁、闭合严密</strong>,有油污或夹不紧会造成读数不准;</li><li>测量小电流时,可把导线在钳口上<strong>绕几圈</strong>,读数除以圈数即得实际电流;</li><li>不要测量<strong>裸导线</strong>时用手接触钳口,注意防护;</li><li>在带电线路上测量,注意安全距离,不要碰触其他带电部分。</li></ul><h2 id="五、考点提示" tabindex="-1">五、考点提示 <a class="header-anchor" href="#五、考点提示" aria-label="Permalink to &quot;五、考点提示&quot;">​</a></h2><ul><li>✅ 钳形电流表<strong>不用断电、不用拆线</strong>就能测电流,靠电流互感器原理。</li><li>✅ 只能<strong>夹单根导线</strong>,且要放在<strong>钳口中央</strong>。</li><li>✅ 多数钳形表<strong>只能测交流</strong>电流。</li><li>⚠️ 易混点:钳形表是&quot;测电流&quot;的,测电压/电阻用万用表。</li></ul><h2 id="六、本节小结" tabindex="-1">六、本节小结 <a class="header-anchor" href="#六、本节小结" aria-label="Permalink to &quot;六、本节小结&quot;">​</a></h2><ul><li>钳形电流表利用电流互感器原理,夹线即可测电流。</li><li>使用要点:单根导线、钳口中央、先大后小选量程。</li><li>多数型号只能测交流;测量中注意钳口清洁密合。</li></ul><h2 id="七、自测练习" tabindex="-1">七、自测练习 <a class="header-anchor" href="#七、自测练习" aria-label="Permalink to &quot;七、自测练习&quot;">​</a></h2><ol><li>(判断)钳形电流表可以在不断开电路的情况下测量电流。( )</li><li>(单选)测量电流时,钳形电流表的钳口应()。 A. 同时夹住多根导线　B. 夹住一根导线并置于钳口中央　C. 夹住零线　D. 接触导线金属芯</li><li>(单选)大多数普通钳形电流表只能测量()电流。 A. 直流　B. 交流　C. 交直流　D. 高频</li><li>(判断)测量小电流时,可将导线在钳口上多绕几圈,再除以圈数得到实际电流。( )</li><li>(判断)钳形电流表是利用电流互感器原理工作的。( )</li></ol><details><summary>参考答案(点击展开)</summary><ol><li><strong>√</strong>。这是钳形表的最大优点。</li><li><strong>B</strong>。只能夹单根导线并置于钳口中央。</li><li><strong>B</strong>。多数普通钳形表只能测交流。</li><li><strong>√</strong>。读数 ÷ 圈数 = 实际电流。</li><li><strong>√</strong>。它就是一个可开合的电流互感器。</li></ol></details>`,23)])])}const u=i(o,[["render",s]]);export{p as __pageData,u as default};
